def parse_documents(source_kind, source_locator=None, original_filename=None, content_type=None, size_bytes=None, sha256=None, requested_ocr_language=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0553000" if __import__("os").path.isdir("./environment_mix/0553000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status = "ok"
    jobs_file = "conversion_jobs.json"
    langs_file = "ocr_languages.json"

    # --- Validate inputs ---
    allowed_source_kind = {"upload", "url", "local_path"}
    if not isinstance(source_kind, str) or source_kind not in allowed_source_kind:
        return _err("VALIDATION_ERROR", "source_kind must be one of: upload, url, local_path", field="source_kind")

    if source_locator is not None and not isinstance(source_locator, str):
        return _err("VALIDATION_ERROR", "source_locator must be a string", field="source_locator")
    if original_filename is not None and not isinstance(original_filename, str):
        return _err("VALIDATION_ERROR", "original_filename must be a string", field="original_filename")
    if content_type is not None and not isinstance(content_type, str):
        return _err("VALIDATION_ERROR", "content_type must be a string", field="content_type")
    if size_bytes is not None:
        if not isinstance(size_bytes, int):
            return _err("VALIDATION_ERROR", "size_bytes must be an integer", field="size_bytes")
        if size_bytes < 0:
            return _err("VALIDATION_ERROR", "size_bytes must be >= 0", field="size_bytes")
    if sha256 is not None:
        if not isinstance(sha256, str):
            return _err("VALIDATION_ERROR", "sha256 must be a string", field="sha256")
        if not re.fullmatch(r"[0-9a-fA-F]{64}", sha256):
            return _err("VALIDATION_ERROR", "sha256 must be a 64-character hex string", field="sha256")

    # Required source details consistency
    if source_kind in {"url", "local_path"}:
        if not source_locator or not isinstance(source_locator, str) or not source_locator.strip():
            return _err("VALIDATION_ERROR", "source_locator is required for source_kind='url' or 'local_path'", field="source_locator")
    # For upload, locator is ignored (but may be stored if provided); no extra requirements.

    if requested_ocr_language is not None and not isinstance(requested_ocr_language, str):
        return _err("VALIDATION_ERROR", "requested_ocr_language must be a string", field="requested_ocr_language")

    # If requested_ocr_language provided, it must reference enabled language at submission time
    if requested_ocr_language is not None:
        langs = _load(langs_file)
        ok_lang = any(
            isinstance(r, dict)
            and r.get("code") == requested_ocr_language
            and r.get("is_enabled") is True
            for r in langs
        )
        if not ok_lang:
            return _err("VALIDATION_ERROR", "requested_ocr_language must reference an enabled ocr_languages.code", field="requested_ocr_language")

    # --- Create job (must always create) ---
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()
    jobs = _load(jobs_file)

    # ID convention: "job_" + uuid4 hex
    job_id = "job_" + uuid.uuid4().hex
    job_row = {
        "id": job_id,
        "status": "queued",
        "source_kind": source_kind,
        "source_locator": source_locator if (source_kind != "upload") else None,
        "original_filename": original_filename,
        "content_type": content_type,
        "size_bytes": size_bytes,
        "sha256": sha256.lower() if isinstance(sha256, str) else None,
        "requested_ocr_language": requested_ocr_language,
        "engine_version": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # Persist
    if not isinstance(jobs, list):
        jobs = []
    jobs.append(job_row)
    _save(jobs_file, jobs)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "job": job_row,
        "meta": {
            "status": status,
            "latency_ms": latency_ms,
        },
    }

def get_ocr_languages(is_enabled=None, engine_provider=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0553000" if __import__("os").path.isdir("./environment_mix/0553000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Validate filters
    if is_enabled is not None and not isinstance(is_enabled, bool):
        return _err("VALIDATION_ERROR", "is_enabled must be a boolean", field="is_enabled")

    allowed_provider = {"tesseract", "paddleocr", "easyocr", "unknown"}
    if engine_provider is not None:
        if not isinstance(engine_provider, str) or engine_provider not in allowed_provider:
            return _err("VALIDATION_ERROR", "engine_provider must be one of: tesseract, paddleocr, easyocr, unknown", field="engine_provider")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit <= 0 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer in [1, 200]", field="limit")

    allowed_sort = {"code", "-code", "display_name", "-display_name", "created_at", "-created_at", "updated_at", "-updated_at"}
    if sort is None:
        sort = "code"
    if not isinstance(sort, str) or sort not in allowed_sort:
        return _err("VALIDATION_ERROR", "sort is not supported", field="sort")

    # Cursor format: base64url(JSON {"offset": int})
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string", field="cursor")
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "offset" not in obj or not isinstance(obj["offset"], int) or obj["offset"] < 0:
                return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
            offset = obj["offset"]
        except (ValueError, json.JSONDecodeError):
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")

    # Business rule: MUST return only enabled rows, derivable solely from ocr_languages
    langs = _load("ocr_languages.json")
    if not isinstance(langs, list):
        langs = []

    rows = []
    for r in langs:
        if not isinstance(r, dict):
            continue
        if r.get("is_enabled") is not True:
            continue
        # Optional filter by is_enabled: since only enabled are returned, is_enabled=false yields empty.
        if is_enabled is not None and is_enabled is False:
            continue
        if engine_provider is not None and r.get("engine_provider") != engine_provider:
            continue
        rows.append(r)

    key = sort.lstrip("-")
    desc = sort.startswith("-")

    def _sort_key(x):
        v = x.get(key)
        # Ensure stable ordering with None last
        none_flag = (v is None)
        return (none_flag, v)

    try:
        rows.sort(key=_sort_key, reverse=desc)
    except TypeError:
        # Fallback: stringification if mixed types
        rows.sort(key=lambda x: (x.get(key) is None, str(x.get(key))), reverse=desc)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total

    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "languages": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "latency_ms": latency_ms,
        },
    }

def list_conversion_jobs(status=None, source_kind=None, requested_ocr_language=None, created_at_gte=None, created_at_lte=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0553000" if __import__("os").path.isdir("./environment_mix/0553000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "status must be one of: queued, running, succeeded, failed, cancelled", field="status")

    allowed_source_kind = {"upload", "url", "local_path"}
    if source_kind is not None:
        if not isinstance(source_kind, str) or source_kind not in allowed_source_kind:
            return _err("VALIDATION_ERROR", "source_kind must be one of: upload, url, local_path", field="source_kind")

    if requested_ocr_language is not None and not isinstance(requested_ocr_language, str):
        return _err("VALIDATION_ERROR", "requested_ocr_language must be a string", field="requested_ocr_language")

    def _parse_rfc3339(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            raise ValueError(field)
        ss = s
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        return datetime.datetime.fromisoformat(ss)

    try:
        dt_gte = _parse_rfc3339(created_at_gte, "created_at_gte")
        dt_lte = _parse_rfc3339(created_at_lte, "created_at_lte")
    except ValueError as e:
        return _err("VALIDATION_ERROR", "timestamp must be RFC 3339", field=str(e))

    if dt_gte is not None and dt_lte is not None and dt_lte < dt_gte:
        return _err("VALIDATION_ERROR", "created_at_lte must be >= created_at_gte", field="created_at_lte")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit <= 0 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer in [1, 200]", field="limit")

    allowed_sort = {"created_at", "-created_at", "updated_at", "-updated_at", "started_at", "-started_at", "finished_at", "-finished_at", "status", "-status"}
    if sort is None:
        sort = "-created_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        return _err("VALIDATION_ERROR", "sort is not supported", field="sort")

    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string", field="cursor")
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "offset" not in obj or not isinstance(obj["offset"], int) or obj["offset"] < 0:
                return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
            offset = obj["offset"]
        except (ValueError, json.JSONDecodeError):
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")

    jobs = _load("conversion_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    rows = []
    for r in jobs:
        if not isinstance(r, dict):
            continue
        if status is not None and r.get("status") != status:
            continue
        if source_kind is not None and r.get("source_kind") != source_kind:
            continue
        if requested_ocr_language is not None and r.get("requested_ocr_language") != requested_ocr_language:
            continue

        if dt_gte is not None or dt_lte is not None:
            ca = r.get("created_at")
            if not isinstance(ca, str):
                continue
            try:
                ca_s = ca[:-1] + "+00:00" if ca.endswith("Z") else ca
                ca_dt = datetime.datetime.fromisoformat(ca_s)
            except ValueError:
                continue
            if dt_gte is not None and ca_dt < dt_gte:
                continue
            if dt_lte is not None and ca_dt > dt_lte:
                continue
        rows.append(r)

    key = sort.lstrip("-")
    desc = sort.startswith("-")

    def _sort_key(x):
        v = x.get(key)
        none_flag = (v is None)
        return (none_flag, v)

    try:
        rows.sort(key=_sort_key, reverse=desc)
    except TypeError:
        rows.sort(key=lambda x: (x.get(key) is None, str(x.get(key))), reverse=desc)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total

    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "jobs": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "latency_ms": latency_ms,
        },
    }

def get_conversion_job(id, **_extra):
    import json, os, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0553000" if __import__("os").path.isdir("./environment_mix/0553000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if not isinstance(id, str) or not id:
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

    jobs = _load("conversion_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    found = None
    for r in jobs:
        if isinstance(r, dict) and r.get("id") == id:
            found = r
            break

    if found is None:
        return _err("NOT_FOUND", "conversion job not found", id=id)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "job": found,
        "meta": {
            "latency_ms": latency_ms,
        },
    }

def cancel_conversion_job(id, reason=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0553000" if __import__("os").path.isdir("./environment_mix/0553000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started_ts = datetime.datetime.utcnow()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        t = s.strip()
        if t.endswith("Z"):
            t = t[:-1]
        try:
            return datetime.datetime.fromisoformat(t)
        except ValueError:
            return None

    def _log(status, job_id=None, detail=None):
        # Best-effort request log; ignore if schema doesn't include it.
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = int((datetime.datetime.utcnow() - started_ts).total_seconds() * 1000)
            logs.append({
                "id": "mnr_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": "cancel_conversion_job",
                "job_id": job_id,
                "status": status,
                "detail": detail,
                "latency_ms": latency_ms,
                "created_at": _now_iso(),
            })
            _save("request_logs.json", logs)
        except Exception:
            return

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        _log("error", job_id=None, detail="VALIDATION_ERROR:id")
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
    if reason is not None and not isinstance(reason, str):
        _log("error", job_id=id, detail="VALIDATION_ERROR:reason")
        return _err("VALIDATION_ERROR", "reason must be a string", field="reason")
    if isinstance(reason, str):
        reason = reason.strip() or None

    # Load jobs store
    jobs = _load("conversion_jobs.json")
    if not isinstance(jobs, list):
        _log("error", job_id=id, detail="NOT_FOUND:store_unavailable")
        return _err("NOT_FOUND", "conversion jobs store is unavailable or corrupted")

    # Find job
    job_idx = None
    for i, j in enumerate(jobs):
        if isinstance(j, dict) and j.get("id") == id:
            job_idx = i
            break
    if job_idx is None:
        _log("error", job_id=id, detail="NOT_FOUND")
        return _err("NOT_FOUND", "conversion job not found", id=id)

    job = jobs[job_idx]
    status = job.get("status")
    terminal = {"succeeded", "failed", "cancelled"}

    # If already terminal, return record unchanged (idempotent) but still log the call.
    if status in terminal:
        latency_ms = int((datetime.datetime.utcnow() - started_ts).total_seconds() * 1000)
        _log("ok", job_id=id, detail="idempotent_noop")
        return {
            "job": job,
            "latency_ms": latency_ms,
            "status": "ok",
        }

    # Validate lifecycle status
    allowed_statuses = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status not in allowed_statuses:
        _log("error", job_id=id, detail="VALIDATION_ERROR:bad_status")
        return _err("VALIDATION_ERROR", "job has invalid status in datastore", field="status", value=status)

    # Enforce valid transition to cancelled
    transitions = {
        "queued": {"running", "cancelled"},
        "running": {"succeeded", "failed", "cancelled"},
        "succeeded": set(),
        "failed": set(),
        "cancelled": set(),
    }
    if "cancelled" not in transitions.get(status, set()):
        _log("error", job_id=id, detail="INVALID_TRANSITION")
        return _err(
            "INVALID_TRANSITION",
            "job cannot be cancelled from its current status",
            from_status=status,
            to_status="cancelled",
            id=id,
        )

    now_iso = _now_iso()
    now_dt = _parse_iso(now_iso)

    # Apply mutation
    mutated = False
    if job.get("status") != "cancelled":
        job["status"] = "cancelled"
        mutated = True

    # Ensure timestamps: finished_at must be set on cancelled; updated_at advanced
    # Also enforce finished_at >= started_at when started_at exists.
    started_at_dt = _parse_iso(job.get("started_at"))
    if started_at_dt is not None and now_dt is not None and now_dt < started_at_dt:
        # If clock skew would violate constraints, clamp to started_at
        job["finished_at"] = job.get("started_at")
    else:
        job["finished_at"] = now_iso
    job["updated_at"] = now_iso
    mutated = True

    # Optional audit detail: record reason if provided (schema doesn't define, but safe to store as extra)
    if reason is not None:
        prev_reason = job.get("cancel_reason")
        if prev_reason != reason:
            job["cancel_reason"] = reason
            mutated = True

    # Persist
    if not mutated:
        # Should not happen, but avoid "success without effect"
        _log("error", job_id=id, detail="CONFLICT:no_effect")
        return _err("CONFLICT", "cancellation request had no effect", id=id)

    jobs[job_idx] = job
    try:
        _save("conversion_jobs.json", jobs)
    except Exception:
        _log("error", job_id=id, detail="CONFLICT:save_failed")
        return _err("CONFLICT", "failed to persist job cancellation", id=id)

    latency_ms = int((datetime.datetime.utcnow() - started_ts).total_seconds() * 1000)
    _log("ok", job_id=id, detail="cancelled")
    return {
        "job": job,
        "latency_ms": latency_ms,
        "status": "ok",
    }

def list_conversion_outputs(job_id, output_type=None, format=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0553000" if __import__("os").path.isdir("./environment_mix/0553000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.utcnow()

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            t = s.strip()
            if t.endswith("Z"):
                t = t[:-1]
            return datetime.datetime.fromisoformat(t)
        except Exception:
            return None

    def _stable_key(row, field):
        v = row.get(field)
        if field in ("created_at", "updated_at"):
            dt = _parse_iso(v)
            return dt if dt is not None else datetime.datetime.min
        if v is None:
            return ""
        return v

    # Validation
    if not isinstance(job_id, str) or not job_id.strip():
        return _err("VALIDATION_ERROR", "job_id must be a non-empty string", field="job_id")

    valid_output_types = {"text", "structured", "artifact_index", "metadata", "log"}
    if output_type is not None:
        if not isinstance(output_type, str) or output_type not in valid_output_types:
            return _err("VALIDATION_ERROR", "output_type is invalid", field="output_type", allowed=sorted(valid_output_types))

    if format is not None and not isinstance(format, str):
        return _err("VALIDATION_ERROR", "format must be a string", field="format")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")

    valid_sorts = {"created_at", "-created_at", "updated_at", "-updated_at", "output_type", "-output_type", "format", "-format"}
    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in valid_sorts:
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort", allowed=sorted(valid_sorts))

    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    # Check job exists
    jobs = _load("conversion_jobs.json")
    job_exists = any(isinstance(j, dict) and j.get("id") == job_id for j in jobs)
    if not job_exists:
        return _err("NOT_FOUND", "conversion job not found", job_id=job_id)

    outputs = _load("conversion_outputs.json")

    # Filter
    filtered = []
    for r in outputs:
        if not isinstance(r, dict):
            continue
        if r.get("job_id") != job_id:
            continue
        if output_type is not None and r.get("output_type") != output_type:
            continue
        if format is not None and r.get("format") != format:
            continue
        filtered.append(r)

    # Sort
    desc = sort.startswith("-")
    field = sort[1:] if desc else sort
    # Deterministic tie-breaker by id
    filtered.sort(key=lambda row: (_stable_key(row, field), str(row.get("id", ""))), reverse=desc)

    # Cursor handling: base64url(json) with fields:
    # {v:1, job_id, output_type, format, sort, offset, exp, sig}
    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8"))
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")

        if not isinstance(obj, dict) or obj.get("v") != 1:
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        # expiry (10 minutes)
        exp = obj.get("exp")
        if not isinstance(exp, str):
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        exp_dt = _parse_iso(exp)
        if exp_dt is None:
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        if datetime.datetime.utcnow() > exp_dt:
            return _err("VALIDATION_ERROR", "cursor is expired", field="cursor")

        # Validate scope matches request
        if obj.get("job_id") != job_id or obj.get("output_type") != output_type or obj.get("format") != format or obj.get("sort") != sort:
            return _err("VALIDATION_ERROR", "cursor does not match request parameters", field="cursor")

        if not isinstance(obj.get("offset"), int) or obj["offset"] < 0:
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")

        # Verify signature to detect tampering (no secret; binds to current store snapshot)
        sig = obj.get("sig")
        if not isinstance(sig, str):
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        snapshot = json.dumps([r.get("id") for r in filtered], ensure_ascii=False, separators=(",", ":"))
        expected = hashlib.sha256((snapshot + f"|{job_id}|{output_type}|{format}|{sort}|{obj['offset']}|{exp}").encode("utf-8")).hexdigest()
        if sig != expected:
            return _err("VALIDATION_ERROR", "cursor is malformed or expired", field="cursor")

        offset = obj["offset"]

    total = len(filtered)
    page = filtered[offset:offset + limit]
    next_cursor = None
    has_more = offset + limit < total
    if has_more:
        exp_dt = datetime.datetime.utcnow() + datetime.timedelta(minutes=10)
        exp = exp_dt.replace(tzinfo=None).isoformat(timespec="seconds") + "Z"
        next_offset = offset + limit
        snapshot = json.dumps([r.get("id") for r in filtered], ensure_ascii=False, separators=(",", ":"))
        sig = hashlib.sha256((snapshot + f"|{job_id}|{output_type}|{format}|{sort}|{next_offset}|{exp}").encode("utf-8")).hexdigest()
        obj = {
            "v": 1,
            "job_id": job_id,
            "output_type": output_type,
            "format": format,
            "sort": sort,
            "offset": next_offset,
            "exp": exp,
            "sig": sig,
        }
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    latency_ms = int((datetime.datetime.utcnow() - started).total_seconds() * 1000)
    return {
        "outputs": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        },
        "sort": sort,
        "status": "ok",
        "latency_ms": latency_ms,
    }

def list_job_artifacts(job_id, artifact_type=None, page_number=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0553000" if __import__("os").path.isdir("./environment_mix/0553000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.utcnow()

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            t = s.strip()
            if t.endswith("Z"):
                t = t[:-1]
            return datetime.datetime.fromisoformat(t)
        except Exception:
            return None

    def _stable_key(row, field):
        v = row.get(field)
        if field in ("created_at", "updated_at"):
            dt = _parse_iso(v)
            return dt if dt is not None else datetime.datetime.min
        if field == "page_number":
            if v is None:
                return -1
            return v if isinstance(v, int) else -1
        if v is None:
            return ""
        return v

    # Validation
    if not isinstance(job_id, str) or not job_id.strip():
        return _err("VALIDATION_ERROR", "job_id must be a non-empty string", field="job_id")

    valid_artifact_types = {"page_image", "embedded_image", "attachment", "table_snapshot", "debug"}
    if artifact_type is not None:
        if not isinstance(artifact_type, str) or artifact_type not in valid_artifact_types:
            return _err("VALIDATION_ERROR", "artifact_type is invalid", field="artifact_type", allowed=sorted(valid_artifact_types))

    if page_number is not None:
        if not isinstance(page_number, int):
            return _err("VALIDATION_ERROR", "page_number must be an integer", field="page_number")
        if page_number < 1:
            return _err("VALIDATION_ERROR", "page_number must be >= 1", field="page_number")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")

    valid_sorts = {"created_at", "-created_at", "updated_at", "-updated_at", "page_number", "-page_number", "artifact_type", "-artifact_type"}
    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in valid_sorts:
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort", allowed=sorted(valid_sorts))

    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    # Check job exists
    jobs = _load("conversion_jobs.json")
    job_exists = any(isinstance(j, dict) and j.get("id") == job_id for j in jobs)
    if not job_exists:
        return _err("NOT_FOUND", "conversion job not found", job_id=job_id)

    artifacts = _load("job_artifacts.json")

    # Filter
    filtered = []
    for r in artifacts:
        if not isinstance(r, dict):
            continue
        if r.get("job_id") != job_id:
            continue
        if artifact_type is not None and r.get("artifact_type") != artifact_type:
            continue
        if page_number is not None and r.get("page_number") != page_number:
            continue
        filtered.append(r)

    # Sort
    desc = sort.startswith("-")
    field = sort[1:] if desc else sort
    filtered.sort(key=lambda row: (_stable_key(row, field), str(row.get("id", ""))), reverse=desc)

    # Cursor handling (same pattern as outputs)
    offset = 0
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8"))
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")

        if not isinstance(obj, dict) or obj.get("v") != 1:
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")

        exp = obj.get("exp")
        if not isinstance(exp, str):
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        exp_dt = _parse_iso(exp)
        if exp_dt is None:
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        if datetime.datetime.utcnow() > exp_dt:
            return _err("VALIDATION_ERROR", "cursor is expired", field="cursor")

        if obj.get("job_id") != job_id or obj.get("artifact_type") != artifact_type or obj.get("page_number") != page_number or obj.get("sort") != sort:
            return _err("VALIDATION_ERROR", "cursor does not match request parameters", field="cursor")

        if not isinstance(obj.get("offset"), int) or obj["offset"] < 0:
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")

        sig = obj.get("sig")
        if not isinstance(sig, str):
            return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
        snapshot = json.dumps([r.get("id") for r in filtered], ensure_ascii=False, separators=(",", ":"))
        expected = hashlib.sha256((snapshot + f"|{job_id}|{artifact_type}|{page_number}|{sort}|{obj['offset']}|{exp}").encode("utf-8")).hexdigest()
        if sig != expected:
            return _err("VALIDATION_ERROR", "cursor is malformed or expired", field="cursor")

        offset = obj["offset"]

    total = len(filtered)
    page = filtered[offset:offset + limit]
    next_cursor = None
    has_more = offset + limit < total
    if has_more:
        exp_dt = datetime.datetime.utcnow() + datetime.timedelta(minutes=10)
        exp = exp_dt.replace(tzinfo=None).isoformat(timespec="seconds") + "Z"
        next_offset = offset + limit
        snapshot = json.dumps([r.get("id") for r in filtered], ensure_ascii=False, separators=(",", ":"))
        sig = hashlib.sha256((snapshot + f"|{job_id}|{artifact_type}|{page_number}|{sort}|{next_offset}|{exp}").encode("utf-8")).hexdigest()
        obj = {
            "v": 1,
            "job_id": job_id,
            "artifact_type": artifact_type,
            "page_number": page_number,
            "sort": sort,
            "offset": next_offset,
            "exp": exp,
            "sig": sig,
        }
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    latency_ms = int((datetime.datetime.utcnow() - started).total_seconds() * 1000)
    return {
        "artifacts": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        },
        "sort": sort,
        "status": "ok",
        "latency_ms": latency_ms,
    }
